        ["EnableNobleGathering"] = "Master gathering-system switch. Disabling it stops new gatherings; ongoing gatherings are settled as cancelled at the next safe campaign hour, and hosts and guests are scheduled to return home. No game restart is required.",
        ["EnableNpcAutomaticNobleGatherings"] = "When enabled, eligible NPCs automatically host gatherings by kingdom. Disabling it stops automatic creation of NPC gatherings; the player can still host gatherings.",
        ["EnableNpcBattleEquipmentRestore"] = "When enabled, equipped items that NPCs lose through gifts, trades, or post-battle capture return to their original slots after 3 full days. Other equipment already in those slots is never overwritten. When disabled, NPCs can still hand over equipment, but no new restoration tasks are registered and existing tasks are not executed. Existing tasks resume when re-enabled. Enabled by default.",
        ["EnableNpcInitiatedLetters"] = "Allows NPCs who already know the player and have a sufficient combined intimacy score to send real couriers proactively.",
        ["EnableNpcRulerPolicy"] = "When enabled, NPC kingdoms formulate and publish policies at the configured intervals. Disabling this stops new policy generation; policies already in force and their records are unaffected.",
        ["EnablePlayerKingdomRebellionImmunity"] = "When the player clan rules a kingdom or the player is its leader, enabling this stops this mod kingdom stability from applying relation modifiers, loyalty modifiers to settlements directly ruled by the king, or kingdom-rebellion checks to that kingdom. Native low-loyalty town rebellions still follow native rules.",
        ["EnableProactiveNpcRequests"] = "When enabled, NPC parties with explicit needs can proactively catch up with the player on the campaign map and initiate dialogue.",
        ["EnableSetsDiagnosticLog"] = "Writes the separate SETS.log for settlement-entry companions and internal unrest diagnostics. Disabling this stops new log entries, while existing logs can still be exported or cleared.",
        ["EnableSetsVerboseDiagnosticLog"] = "Records frequent diagnostics such as per-frame protection, command refreshes, and troop-spawn progress. Enable while investigating stalls; disabling this retains key logs for conflict starts, waves, victories, and exceptions.",
        ["EnableWeeklyReportMapNotifications"] = "When enabled, a clickable message appears at the bottom right of the campaign map when a weekly report is generated. When disabled, no message appears, and reports generated while disabled are not queued for later notification. Enabled by default.",
        ["EnableWeeklyReportReadingXpReward"] = "When enabled, opening a weekly report from a map notification and staying for 10 full seconds accumulates experience from the character counts of its three columns. After every 20 reports studied, Charm, Leadership, and Steward experience is awarded to the player in one batch.",
        ["EnableWorldDiplomacy"] = "When enabled, kingdoms publish diplomatic declarations, negotiate, and take diplomatic actions on their own. Diplomacy and scribe drafting reuse the event and kingdom-rebellion API, falling back to the main API if the configuration is incomplete. When disabled, native kingdom diplomatic decisions resume.",
        ["EnableWorldDiplomacyMapNotifications"] = "Delivered diplomatic declarations appear as text messages at the bottom left, instead of right-side notifications. Disabling this does not affect negotiations, distribution, bulletin material, or kingdom notices.",
        ["ExportGcczDebugLog"] = "Copies GCCZ_Debug.log from the current module Logs folder to the desktop as a separate file with a timestamp in its name.",
        ["ExportNoblePrisonerEscortLog"] = "Copies NoblePrisonerEscort.log to the desktop as a separate file for investigating prisoner spawning, scene executions, and retreats from wilderness meetings.",
        ["ExportSetsDiagnosticLog"] = "Copies SETS.log from the current module Logs folder to the desktop as a separate file with a timestamp in its name.",
        ["GcczDiagnosticLogMaxSizeMegabytes"] = "GCCZ_Debug.log rotates automatically at this limit; the previous file is retained as GCCZ_Debug.previous.log. Default: 16 MB.",
        ["GcczNpcResponseLimit"] = "Limits ambient NPC replies per player utterance, semantic action, or player attack event in an active GCCZ town scene.",
        ["GcczNpcResponseUnlimited"] = "Removes the configured numeric cap in active GCCZ town scenes while retaining event deduplication and queue safety.",
        ["HealthThreshold"] = "Configure Health Threshold.",
        ["IntimacyPregnancyChancePercent"] = "Probability that the woman becomes pregnant after the intimacy tag confirms that intercourse and internal ejaculation occurred this exchange. 0 means never, and 100 means always. Default: 50%.",
        ["ManagePolicyEffectModules"] = "Separately configures retrievable effect modules for player, local, NPC ruler, and vassal-state policies. Affects only policies initiated after saving.",
        ["MarriageCandidateMaxAge"] = "Used to filter the clan list of marriage candidates. Default: 55.",
        ["MarriageCandidateMaxAgeGap"] = "Used to filter the clan list of marriage candidates. Default: 25.",
        ["MarriageRequireOppositeGender"] = "Retained for compatibility with old configurations; the current marriage system allows same-sex marriages. Disabled by default.",
        ["MinimumClanTier"] = "Configure Minimum Clan Tier.",
        ["NewsMode"] = "Choose weekly reports or bulletins; the two modes are mutually exclusive. Switching modes preserves historical archives.",
        ["NobleGatheringCost"] = "Shared by player and NPC hosts; the actual host pays the cost. Default: 50000 denars; 0 means free.",
        ["NobleGatheringDurationDays"] = "Shared by player and NPC gatherings. Default: 5 days. Changes affect only gatherings created afterward; gatherings already underway keep their original end date.",
        ["NobleGatheringInvitedClanRelationReward"] = "Shared by player and NPC gatherings; settled only once per gathering for the host and each invited clan leader. Default: 5; 0 means no relation increase. Changes affect only gatherings created afterward.",
        ["NpcInitiatedLetterChanceMultiplier"] = "Probability per scan equals the combined intimacy score multiplied by this value. Default: 0.25, so a score of 100 gives a 25% chance.",
        ["NpcInitiatedLetterDebugLog"] = "Records candidate scores, probabilities, motives, cooldowns, and reasons for skipping in Mod_Logic.txt.",
        ["NpcInitiatedLetterGlobalCooldownDays"] = "In-game days before another proactive letter can start after any NPC proactively sends one. Default: 5 days.",
        ["NpcInitiatedLetterHighScoreCooldownDays"] = "Sender cooldown for an NPC with a combined score of 100. Default: 14 days.",
        ["NpcInitiatedLetterLowScoreCooldownDays"] = "Sender cooldown for an NPC with the lowest combined score. Default: 45 days.",
        ["NpcInitiatedLetterMinBondScore"] = "Minimum candidate score after averaging private relation and the trust value used for letters. Default: 10.",
        ["NpcInitiatedLetterMotiveFatigueDays"] = "Duration of reduced weight when the same NPC repeats the same type of letter-writing motive. Default: 30 days.",
        ["NpcInitiatedLetterMotiveFatigueMultiplier"] = "Weight multiplier during the fatigue period for greeting, recent-news, event, emotional, request, or diplomacy motives. Default: 0.25.",
        ["NpcInitiatedLetterPublicTrustCap"] = "Maximum positive or negative contribution of public trust to the trust value used for letters. Default: ±20.",
        ["NpcInitiatedLetterQuietDays"] = "Minimum in-game days after communicating with this NPC through any channel before a proactive letter is allowed. Default: 3 days.",
        ["NpcInitiatedLetterScanIntervalHours"] = "In-game hours between scans of proactive-letter candidates. Default: 24 hours.",
        ["NpcInitiatedLetterTargetChars"] = "Target character count of an NPC proactive letter body. Default: 220 characters.",
        ["NpcInitiatedLetterTestMode"] = "Raises the trigger probability to 100% and removes proactive-letter cooldowns. Still requires the NPC to know the player, have a valid location, and have a real motive.",
        ["NpcNobleGatheringIntervalDays"] = "In-game days between scheduling two automatic gatherings in the same kingdom. Default: 21 days. Calculated separately per kingdom; changes are used the next time a gathering is rescheduled.",
        ["NpcRulerPolicyApiSourceDropdown"] = "Reuses the selected chain URL, key, model, and address-parsing rules. Incomplete selected configurations automatically fall back to the main API. Explicitly selecting preprocessing is unaffected by the ordinary preprocessing API switch.",
        ["NpcRulerPolicyCheckIntervalDays"] = "In-game days between checks for whether a new NPC policy is needed. Default: 7 days; adjustable from 1 to 30 days. No policy is generated this round if no kingdom is eligible.",
        ["NpcRulerPolicyCustomMaxTokens"] = "Used only when Follow selected API tokens is disabled. Affects only NPC ruler policies; allows 1000–100000 and does not change global limits for other APIs.",
        ["NpcRulerPolicyFollowSelectedApiTokens"] = "When enabled, uses the maximum output tokens of the API source actually in effect. If it falls back to the main API, the main API token limit is used instead. When disabled, always uses the custom policy value below.",
        ["NpcRulerPolicyIntervalDays"] = "Minimum in-game days between two policy drafts in the same NPC kingdom. Default: 7 days; adjustable from 1 to 30 days. Normal drafts that are pending, approved, or rejected all count toward the cooldown. Player publication or renewal of a vassal-state policy is exempt, but suppresses NPC ruler policies in that target vassal state for this many days from that day onward.",
        ["OpenCustomPromptTextStoreFolderAction"] = "Opens the CustomPrompts folder, where each set of prompt JSON files can be edited directly.",
        ["PlayerNotorietyCourierRecentDistanceMultiplier"] = "When the player sends a letter, the courier chain can let the target NPC know about recent player actions if the distance is less than the player vision range multiplied by this value. Default: 3.0.",
        ["PlayerNotorietyDebugLogs"] = "When enabled, writes logs about player notoriety records, awareness checks, summaries, and injection to Mod_Logic.txt.",
        ["PlayerNotorietyMajorPromptChars"] = "Target character count and hard limit for the summary of the player public major history; also caps the history injected into the main chain when an NPC knows that history. AI rewrites the entire old summary instead of appending to its end. Unsummarized raw material is not injected directly into the main chain. Default: 300.",
        ["PlayerNotorietySummaryIntervalDays"] = "In-game days between attempts to update the rolling summary of the player public history material. Default: 3 days.",
        ["PlayerPolicyApiSourceDropdown"] = "Reuses the selected chain URL, key, model, and address-parsing rules. Incomplete selected configurations automatically fall back to the main API. Explicitly selecting preprocessing is unaffected by the ordinary preprocessing API switch.",
        ["PlayerPolicyAutoDraftApiSourceDropdown"] = "Selects only whether AI drafting uses the main chain, preprocessing, or postprocessing. Default: preprocessing. Incomplete selected configurations automatically fall back to the main endpoint; the policy-review endpoint is unaffected.",
        ["PlayerPolicyCustomMaxTokens"] = "Used only when Follow selected API tokens is disabled. Affects only player policies; allows 1000–100000 and does not change global limits for other APIs.",
        ["PlayerPolicyEffectModuleDetailCount"] = "Retains old-configuration compatibility: saved values can still be 1–30, with a default of 6. At most 8 detailed rules are ultimately injected into stage two; values above 8 are treated as 8. This does not limit the internal ONNX candidate pool. Higher values consume more prompt text and tokens.",
        ["PlayerPolicyEffectPostprocessMaxTokens"] = "Maximum output tokens for the player policy stage-two effects JSON. Default: 5000; the actual value never exceeds the player policy token limit currently in effect above.",
        ["PlayerPolicyFollowSelectedApiTokens"] = "When enabled, uses the maximum output tokens of the API source actually in effect. If it falls back to the main API, the main API token limit is used instead. When disabled, always uses the custom policy value below.",
        ["PolicyRecentActiveCount"] = "Maximum recent active policies from the current kingdom read by player review and NPC generation. Default: 2; 0 disables this. Missing entries are not filled from elsewhere, and dialogue is unaffected.",
        ["PolicyRelatedActiveCount"] = "Reads the remaining active policies from all kingdoms by relevance. Default: 3. Deduplicates without a similarity threshold; 0 disables this, and dialogue is unaffected.",
        ["PreserveSceneAsteriskActions"] = "When enabled, action content enclosed in **...** or *...* is not removed even if Preserve scene-shout action/inner-thought descriptions is disabled.",
        ["ProactiveNpcKnownMajorMultiplier"] = "Multiplier for need-driven proactive-contact probability when the NPC already knows the player major history. Default: 2.0.",
        ["ProactiveNpcMinNeedUrgency"] = "Minimum need urgency required for NPC proactive contact; treated as 0 at runtime in test mode. Normal-play default: 60.",
        ["ProactiveNpcNotorietyChanceMultiplier"] = "Multiplier converting effective player notoriety into additional NPC proactive-contact probability. Normal-play default: 0.35.",
        ["ProactiveNpcRequestChancePercent"] = "Scaling value for candidate NPC trigger probability. Normal-play default: 35; can be raised to 100 for testing.",
        ["ProactiveNpcRequestClanDebtThreshold"] = "Clan financial-pressure contact can trigger when the NPC clan debt to the kingdom exceeds this value. 0 ignores debt. Normal-play default: 5000.",
        ["ProactiveNpcRequestClanGoldThreshold"] = "Clan financial-pressure contact can trigger when the NPC clan treasury is below this value. 0 ignores the treasury. Normal-play default: 15000.",
        ["ProactiveNpcRequestDistanceMultiplier"] = "Maximum distance between a candidate NPC and the player is the player vision range multiplied by this value. Normal-play default: 1.0.",
        ["ProactiveNpcRequestFiefGarrisonThreshold"] = "Fief-governance-anxiety contact can trigger when the garrison in an NPC clan fief is at or below this value. 0 ignores garrisons. Normal-play default: 80.",
        ["ProactiveNpcRequestFiefLoyaltyThreshold"] = "Fief-governance-anxiety contact can trigger when loyalty in an NPC clan fief is at or below this value. 0 ignores loyalty. Normal-play default: 35.",
        ["ProactiveNpcRequestFiefSecurityThreshold"] = "Fief-governance-anxiety contact can trigger when security in an NPC clan fief is at or below this value. 0 ignores security. Normal-play default: 35.",
        ["ProactiveNpcRequestFoodDaysThreshold"] = "Food-shortage contact can trigger when an NPC party has at most this many days of food left or is already starving. Normal-play default: 2 days.",
        ["ProactiveNpcRequestGlobalCooldownHours"] = "Hours before the next proactive contact can start after any proactive contact starts. Normal-play default: 24 hours.",
        ["ProactiveNpcRequestGreetingGlobalCooldownDays"] = "Shared hard cooldown after an NPC with a private relation above 20 proactively catches up with the player or sends a greeting letter. Default: 42 days.",
        ["ProactiveNpcRequestHeroCooldownDays"] = "Days before the same NPC can approach the player again with the same type of need after proactive contact. Normal-play default: 14 days.",
        ["ProactiveNpcRequestIsolationInfluenceThreshold"] = "Combined with ally count, lack-of-allies contact can trigger when NPC clan influence is at or below this value. 0 ignores influence. Normal-play default: 40.",
        ["ProactiveNpcRequestIsolationMaxFriendlyClans"] = "Combined with low influence or hostile relations, lack-of-allies contact can trigger when the number of friendly clans in the same kingdom with an NPC clan relation of at least 20 is at or below this value. Normal-play default: 1.",
        ["ProactiveNpcRequestLowMoraleThreshold"] = "Low-morale contact can trigger when an NPC lord party morale is at or below this value. 0 disables this need. Normal-play default: 35.",
        ["ProactiveNpcRequestMarriageAdultClanThreshold"] = "Succession/marriage-pressure contact can trigger when the number of adult core members of the NPC clan is at or below this value and an adult unmarried clan member exists. Normal-play default: 3.",
        ["ProactiveNpcRequestMinClanTier"] = "Applies when test mode is disabled. NPC proactive contact does not trigger if the player clan tier is below this value.",
        ["ProactiveNpcRequestMoneyGoldThreshold"] = "Money-shortage contact can trigger when the NPC lord available cash is below this value. At runtime, it never falls below the native party cash floor. Default: 5000.",
        ["ProactiveNpcRequestMoneyWageDaysThreshold"] = "Money-shortage contact can trigger when an NPC lord cash can pay at most this many days of wages. 0 checks only the cash threshold and unpaid wages. Normal-play default: 2 days.",
        ["ProactiveNpcRequestMountRatioThresholdPercent"] = "Mount-shortage/low-mobility contact can trigger when mounts in the NPC lord party are below this percentage of party members. 0 disables this need. Normal-play default: 25.",
        ["ProactiveNpcRequestMountShortageWeight"] = "Candidate-weight and trigger-probability multiplier for mount-shortage/purchase requests in map proactive contact and proactive letters. Default: 0.35; 0 retains the need check but prevents proactive initiation. Map pursuit still uses 1.00 in test mode.",
        ["ProactiveNpcRequestOverburdenRatioThresholdPercent"] = "Overburden-pressure contact can trigger when the NPC lord party total load reaches this percentage of inventory capacity. Normal-play default: 92.",
        ["ProactiveNpcRequestPrisonerRatioThresholdPercent"] = "An NPC lord can initiate prisoner overload or ransom contact when the current prisoner count reaches this percentage of prisoner capacity. The normal-play default is 90; 100 means nearly full capacity, and values above 100 trigger only when over capacity.",
        ["ProactiveNpcRequestRomanticInteractionGlobalCooldownDays"] = "Shared hard cooldown for intimate interactions with an opposite-sex NPC whose private relation is above 30, across map pursuit, proactive letters, and companion chats within the party. Default: 21 days.",
        ["ProactiveNpcRequestScanIntervalHours"] = "In-game hours between scans of nearby NPC parties with needs. Normal-play default: 6 hours.",
        ["ProactiveNpcRequestTerritorialInterrogationGlobalCooldownDays"] = "Shared hard cooldown after a territorial interrogation successfully starts. Default: 42 days.",
        ["ProactiveNpcRequestTerritorialInterrogationSettlementRangeMultiplier"] = "When the player is within the player vision range multiplied by this value of a kingdom settlement, its lords of a different culture who do not know the player history can proactively question the player origin and purpose. Default: 3.0.",
        ["ProactiveNpcRequestTestMode"] = "When enabled, Tier 0 players can trigger proactive contact. Use high probabilities and short cooldowns to test contact. Disabled by default for normal play.",
        ["ProactiveNpcRequestTroopRatioThresholdPercent"] = "Troop-shortage contact can trigger when the NPC lord current party size is below this percentage of the party-size limit. Normal-play default: 45; can be raised to 90 or 100 for testing.",
        ["ProactiveNpcRequestTypeFatigueDays"] = "In-game days of greatly reduced trigger probability for a request type after the player receives it. 0 disables type fatigue. Default: 10 days.",
        ["ProactiveNpcRequestTypeFatigueMultiplier"] = "During type fatigue, multiplies both need-driven and notoriety-driven probabilities by this value and lowers the need priority among candidates. Default: 0.20.",
        ["RestoreDefaultWorldDiplomacyPrompt"] = "Restores the mod default preference text after confirmation. Restores only text preferences; does not reset this page event limits, distribution, length, or protection-period settings.",
        ["SetsDiagnosticLogMaxSizeMegabytes"] = "SETS.log rotates automatically at this limit; the previous file is retained as SETS.previous.log. Default: 16 MB.",
        ["ShowNobleGatheringGuestArrivalMessages"] = "Controls colored messages at the bottom left when guests arrive at a player-hosted gathering. Disabling it hides only the messages; arrival checks, gathering state, and rewards are unaffected.",
        ["UseAiEvaluatedCustomPolicyCost"] = "When enabled, AI evaluates the required denars from policy scale and implementation difficulty. If denars are insufficient, all policy effects are reduced in proportion to the actual contribution. When disabled, the fixed denar cost below is used.",
        ["UseDetailedSceneSpeechPrompt"] = "When disabled, detailed action/inner-thought text is still used, but action descriptions and inner thoughts are filtered from the output. When enabled, action descriptions and inner thoughts are retained.",
        ["WeeklyReportLengthPreset"] = "1 = 200–400 characters; 2 = 200–800 characters; 3 = 200–1200 characters; 4 = 200–1500 characters. Shared by world and kingdom weekly reports. Default: 2.",
        ["WeeklyReportPopupBodyFontSize"] = "Affects only the body of the large popup for the latest kingdom weekly report, not other interfaces. Default: 18.",
        ["WeeklyReportReadingXpPerHundredChars"] = "Length multiplier for weekly-report reading rewards. Default: 20, meaning 20 experience in the corresponding skill per 100 valid characters/words in each column.",
        ["WeeklyReportReadingXpSkillCap"] = "Maximum experience per skill from one weekly report. Default: 100; 0 disables weekly-report reading experience.",
        ["WeeklyReportRequestsPerMinute"] = "Limits the weekly-report generation request rate during development. Default: 5; maximum 20. Helps accommodate RPM or concurrency limits of some API channels.",
        ["WorldDiplomacyActivityDropdown"] = "Low: at most 2 kingdoms; moderate: at most 3; high: at most 5, all including the initiating kingdom. Selects only kingdoms with actual diplomatic matters and does not fill the count artificially. Default: moderate. This is the participant count for one event, not the number of concurrent events.",
        ["WorldDiplomacyContinentSpreadDays"] = "Schedules when local nobles and civilians learn of diplomatic declarations according to distance. Default: 21 days. Does not control how often events automatically start or replace court delivery times.",
        ["WorldDiplomacyCourtMaxDeliveryDays"] = "Allocates court delivery times by distance. Controls delivery to the farthest court and the relay pace for one round of a new event; not every kingdom waits this fixed number of days. Default: 7 days; lower values produce more frequent replies.",
        ["WorldDiplomacyDeclarationMaxCharacters"] = "Shared length range for AI-generated diplomatic declarations, responses, and scribe drafts, including punctuation. Default maximum: 500 characters; adjustable from 1 to 1000. Values below the minimum length are treated as the minimum. Does not limit player-written edits.",
        ["WorldDiplomacyDeclarationMinCharacters"] = "Shared length range for AI-generated diplomatic declarations, responses, and scribe drafts, including punctuation. Default minimum: 100 characters; adjustable from 1 to 1000. Does not limit player-written edits.",
        ["WorldDiplomacyHistoryCompressionTargetThousands"] = "Combined target for the long-term snapshot and protected facts after each compression batch. Default: 48, about 48k tokens; cap: 60k. Declarations take only relevant material, not the whole snapshot. Actual summaries are also limited by the selected API maximum output tokens.",
        ["WorldDiplomacyHistoryCompressionTriggerThousands"] = "Start batched compression when the long-term diplomacy archive reaches this estimated size. Default: 800 (about 800k tokens); controls backlog and frequency, not history carried by each declaration. Total declaration input has a separate 32k estimated-token cap, and each compression batch has a separate 128k input cap.",
        ["WorldDiplomacyMaxConcurrentOrdinaryRounds"] = "Shared by ordinary automatic diplomacy and policy triggers; default: 3 events. When full, policy work remains pending while existing talks continue replying and finish. Lowering the limit does not cancel existing events. At most 1 additional event opens per day; player diplomacy and verbal-promise events do not use these slots.",
        ["WorldDiplomacyOffensiveWarCooldownDays"] = "Minimum days after a kingdom starts a war before it can initiate another new war. Default: 42 days. Does not limit publication frequency for other diplomatic declarations.",
        ["WorldDiplomacyPeaceProtectionDays"] = "After two kingdoms make peace, ordinary diplomatic disputes cannot restart war during this period. Default: 21 days; 0 disables this protection. Other war-declaration eligibility restrictions are unaffected.",
        ["WorldDiplomacyRoundLengthDropdown"] = "Typical end time for new events: compact about 15 days, standard about 21 days, relaxed about 28 days. Events may finish early on reaching an outcome or extend briefly to conclude. Default: standard; affects only new events.",
        ["WorldDiplomacyStartNewGameAtPeace"] = "Applies only to newly created saves, ending kingdom wars already present at the start. Disabled by default; toggling this does not reset wars in the current save.",
        ["WorldDiplomacyThreatComplianceIssuerRelationReward"] = "After the target kingdom explicitly complies with a condemnation or ultimatum, leaders of the issuing kingdom formal, non-mercenary vassal clans gain this relation with the current king. Settled only once per threat. Default: 10; 0 disables the reward.",
        ["WorldDiplomacyTradeAllianceFailedProposalCooldownDays"] = "After a trade or alliance proposal fails, the same proposing kingdom temporarily cannot make the same type of proposal to the same target. Reverse-direction proposals and the other proposal type are tracked separately. Default: 168 days; 0 disables this.",
    };

